INSERT INTO public.user_roles (user_id, role) SELECT id, 'admin'::public.app_role FROM auth.users WHERE lower(email) = lower('kendrickchristopher@hotmail.com') ON CONFLICT (user_id, role) DO NOTHING; CREATE OR REPLACE FUNCTION public.grant_seed_admin() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $func$ BEGIN IF lower(NEW.email) = lower('kendrickchristopher@hotmail.com') THEN INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'admin'::public.app_role) ON CONFLICT (user_id, role) DO NOTHING; END IF; RETURN NEW; END; $func$; REVOKE EXECUTE ON FUNCTION public.grant_seed_admin() FROM PUBLIC, anon, authenticated; DROP TRIGGER IF EXISTS on_auth_user_created_seed_admin ON auth.users; CREATE TRIGGER on_auth_user_created_seed_admin AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.grant_seed_admin();